// Preparar contexto completo del video para reciclaje
const item = $input.first();
const fields = item.json.fields || item.json;

const videoId = item.json.id || 'ID_DESCONOCIDO';

// Datos del video original
const titulo = fields.titulo || 'Sin titulo';
const hook = fields.hook || '';
const guion = fields.guion || fields.cuerpo || '';
const cta = fields.cta || '';
const pilar = fields.pilar || 'Herramientas';
const formato = fields.formato || 'Video corto';
const hashtags = fields.hashtags || '';
const plataforma = fields.plataforma || 'Instagram/TikTok';
const fecha_publicacion = fields.fecha_publicacion || '';

// Metricas de performance (si existen)
const views = fields.views || fields.reproducciones || 0;
const likes = fields.likes || 0;
const comentarios = fields.comentarios || 0;
const shares = fields.shares || fields.compartidos || 0;
const saves = fields.saves || fields.guardados || 0;
const reach = fields.reach || fields.alcance || 0;
const engagementRate = fields.engagement_rate || (views > 0 ? ((likes + comentarios + shares) / views * 100).toFixed(2) : 0);
const recycle_count = fields.recycle_count || 0;

// Analisis de performance para el prompt
const performanceLevel = engagementRate > 5 ? 'MUY ALTO' :
  engagementRate > 3 ? 'ALTO' :
  engagementRate > 1 ? 'MEDIO' : 'BAJO';

const prompt = `Eres el estratega de contenido de NOA, una aplicacion para padres de adolescentes con Altas Capacidades Cognitivas (AACC).

Tu tarea es reciclar y reutilizar el siguiente contenido de video EXITOSO para generar multiples formatos derivados.

--- DATOS DEL VIDEO ORIGINAL ---
Titulo: ${titulo}
Hook: ${hook}
Guion: ${guion}
CTA: ${cta}
Pilar: ${pilar}
Formato original: ${formato}
Plataforma: ${plataforma}
Fecha publicacion: ${fecha_publicacion}

--- METRICAS DE PERFORMANCE ---
Reproduccion: ${views.toLocaleString()} views
Likes: ${likes.toLocaleString()}
Comentarios: ${comentarios}
Compartidos: ${shares}
Guardados: ${saves}
Alcance: ${reach.toLocaleString()}
Engagement rate: ${engagementRate}%
Nivel de performance: ${performanceLevel}
Veces reciclado anteriormente: ${recycle_count}

--- INSTRUCCIONES ---
Basandote en el contenido y su nivel de performance (${performanceLevel}), genera exactamente 8 formatos de contenido reciclado:

1. HOOK_1: Nuevo gancho angulo emocional diferente al original
2. HOOK_2: Nuevo gancho angulo practico/herramienta
3. HOOK_3: Nuevo gancho angulo estadistica o dato sorprendente
4. GUION_VARIACION_1: Guion completo reformulado (mismo mensaje, nueva estructura)
5. GUION_VARIACION_2: Guion con caso de uso especifico diferente
6. GUION_VARIACION_3: Version mas corta (30 segundos max)
7. CARRUSEL: Estructura de 5-7 diapositivas para carrusel de Instagram
8. POST_EMAIL: Fragmento adaptado para email newsletter (intro + cuerpo + CTA)
9. HISTORIA: Adaptacion para Instagram Stories (3 pantallas)
10. POST_TEXTO: Version solo texto para LinkedIn o feed sin video
11. GUION_ANUNCIO: Version corta para anuncio de pago (15 segundos)
12. FAQ: 3 preguntas frecuentes derivadas del tema con respuestas

Responde UNICAMENTE con un JSON valido:
{
  "video_id_original": "${videoId}",
  "titulo_original": "${titulo}",
  "nivel_performance": "${performanceLevel}",
  "contenidos_reciclados": [
    {
      "tipo": "HOOK_1",
      "variacion_numero": 1,
      "titulo": "Titulo descriptivo",
      "contenido": "El contenido completo",
      "plataforma_objetivo": "Instagram/TikTok",
      "longitud_estimada_seg": 0,
      "notas": "Instrucciones de uso"
    }
  ]
}`;

return [{
  json: {
    prompt: prompt,
    video_id: videoId,
    titulo: titulo,
    pilar: pilar,
    formato: formato,
    metricas: {
      views: views,
      likes: likes,
      comentarios: comentarios,
      shares: shares,
      saves: saves,
      engagement_rate: engagementRate,
      performance_level: performanceLevel
    },
    recycle_count_actual: recycle_count,
    campos_originales: fields
  }
}];

