// Parsear contenidos reciclados de la respuesta de Claude
const claudeResponse = $input.first().json;
const contexto = $('Code: Preparar Prompt Reciclaje').first().json;

if (!claudeResponse.content || !claudeResponse.content[0] || !claudeResponse.content[0].text) {
  throw new Error('Respuesta de Claude vacia o invalida para reciclaje');
}

const rawText = claudeResponse.content[0].text;

let jsonString = rawText;
const jsonMatch = rawText.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  jsonString = jsonMatch[0];
}

let parsed;
try {
  parsed = JSON.parse(jsonString);
} catch (e) {
  throw new Error(`Error parseando JSON de reciclaje: ${e.message}\nPrimeros 500 chars: ${rawText.substring(0, 500)}`);
}

if (!parsed.contenidos_reciclados || !Array.isArray(parsed.contenidos_reciclados)) {
  throw new Error('La respuesta no contiene el array contenidos_reciclados');
}

const fechaHoy = new Date().toISOString().split('T')[0];

// Mapeo de tipo a categoria para Airtable
const CATEGORIAS = {
  'HOOK_1': 'HOOK',
  'HOOK_2': 'HOOK',
  'HOOK_3': 'HOOK',
  'GUION_VARIACION_1': 'GUION_VARIACION',
  'GUION_VARIACION_2': 'GUION_VARIACION',
  'GUION_VARIACION_3': 'GUION_VARIACION',
  'CARRUSEL': 'CARRUSEL',
  'POST_EMAIL': 'EMAIL',
  'HISTORIA': 'HISTORIA',
  'POST_TEXTO': 'POST_TEXTO',
  'GUION_ANUNCIO': 'ANUNCIO',
  'FAQ': 'FAQ'
};

const contenidosFormateados = parsed.contenidos_reciclados.map((contenido, index) => ({
  json: {
    fields: {
      video_id_original: contexto.video_id,
      titulo_original: contexto.titulo,
      tipo: contenido.tipo || `RECICLADO_${index + 1}`,
      categoria: CATEGORIAS[contenido.tipo] || 'OTRO',
      variacion_numero: contenido.variacion_numero || index + 1,
      titulo: contenido.titulo || `${contenido.tipo} - ${contexto.titulo}`,
      contenido: contenido.contenido || '',
      plataforma_objetivo: contenido.plataforma_objetivo || 'Instagram/TikTok',
      longitud_estimada_seg: contenido.longitud_estimada_seg || 0,
      notas: contenido.notas || '',
      pilar: contexto.pilar,
      estado: 'BORRADOR_RECICLADO',
      fecha_creacion: fechaHoy,
      performance_original: contexto.metricas.performance_level,
      engagement_original: contexto.metricas.engagement_rate,
      modelo_ia: 'claude-opus-4-5',
      tipo_contenido: 'RECICLADO'
    },
    _video_id: contexto.video_id,
    _recycle_count_actual: contexto.recycle_count_actual
  }
}));

return contenidosFormateados;

// Separar los contenidos reciclados por tipo para guardar en tablas especificas
const items = $input.all();

// Clasificar cada item
const hooks = items.filter(i => (i.json.fields.categoria || '') === 'HOOK');
const guionesVariacion = items.filter(i => (i.json.fields.categoria || '') === 'GUION_VARIACION');
const carrusel = items.filter(i => (i.json.fields.categoria || '') === 'CARRUSEL');
const email = items.filter(i => (i.json.fields.categoria || '') === 'EMAIL');
const historia = items.filter(i => (i.json.fields.categoria || '') === 'HISTORIA');
const postTexto = items.filter(i => (i.json.fields.categoria || '') === 'POST_TEXTO');
const anuncio = items.filter(i => (i.json.fields.categoria || '') === 'ANUNCIO');
const faq = items.filter(i => (i.json.fields.categoria || '') === 'FAQ');

const videoId = items[0]?.json?._video_id || 'ID_DESCONOCIDO';
const recycle_count_actual = items[0]?.json?._recycle_count_actual || 0;

return [{
  json: {
    todos_los_contenidos: items.map(i => i.json.fields),
    total_contenidos: items.length,
    resumen_por_tipo: {
      hooks: hooks.length,
      guiones_variacion: guionesVariacion.length,
      carrusel: carrusel.length,
      email: email.length,
      historia: historia.length,
      post_texto: postTexto.length,
      anuncio: anuncio.length,
      faq: faq.length
    },
    video_id: videoId,
    nuevo_recycle_count: recycle_count_actual + 1,
    fecha_reciclaje: new Date().toISOString().split('T')[0]
  }
}];

// Separar y volver a emitir cada contenido individualmente para guardar en Airtable
const grouped = $input.first().json;
const todos = grouped.todos_los_contenidos || [];

// Devolver cada contenido como item separado para el nodo de Airtable (que itera sobre items)
return todos.map(contenido => ({
  json: {
    fields: contenido,
    _video_id: grouped.video_id,
    _nuevo_recycle_count: grouped.nuevo_recycle_count
  }
}));

// Agregar todos los registros creados para el paso siguiente
const creados = $input.all();
const primerItem = creados[0];

return [{
  json: {
    total_creados: creados.length,
    video_id: primerItem?.json?._video_id || primerItem?.json?.fields?.video_id_original || 'ID_DESCONOCIDO',
    nuevo_recycle_count: primerItem?.json?._nuevo_recycle_count || 1,
    ids_creados: creados.map(c => c.json.id).filter(Boolean)
  }
}];

// Construir resumen de reciclaje para notificacion
const actualizacion = $input.first();
const agregados = $('Code: Agregar Creados').first().json;
const contexto = $('Code: Preparar Prompt Reciclaje').first().json;
const agrupados = $('Code: Agrupar por Tipo').first().json;

const resumenTipos = Object.entries(agrupados.resumen_por_tipo || {})
  .filter(([_, count]) => count > 0)
  .map(([tipo, count]) => `• ${tipo.replace('_', ' ')}: ${count}`)
  .join('\n');

const mensaje = {
  text: `*NOA - Reciclaje de Contenido Completado*`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: 'Contenido Reciclado Generado'
      }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Video Original:* ${contexto.titulo}` },
        { type: 'mrkdwn', text: `*Performance:* ${contexto.metricas.performance_level}` },
        { type: 'mrkdwn', text: `*Engagement:* ${contexto.metricas.engagement_rate}%` },
        { type: 'mrkdwn', text: `*Veces reciclado:* ${agregados.nuevo_recycle_count}` }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Total generado:* ${agregados.total_creados} formatos\n\n*Por tipo:*\n${resumenTipos}`
      }
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Ver Contenido Reciclado' },
          url: `https://airtable.com/${process.env.AIRTABLE_BASE_ID || 'BASE_ID'}/Contenido_Reciclado`,
          style: 'primary'
        }
      ]
    }
  ]
};

return [{ json: mensaje }];

const error = $input.first();

const errorInfo = {
  workflow: 'NOA - Reciclaje de Contenido',
  timestamp: new Date().toISOString(),
  error_message: error.json.message || error.json.error || JSON.stringify(error.json),
  context: 'Error en pipeline de reciclaje'
};

console.error('Error en workflow Reciclaje:', JSON.stringify(errorInfo));

return [{ json: errorInfo }];
